/* =============================== PORTAL VENDOR =============================== */
function vOrders(v) { return VORDERS.filter(o => o.vendor === v.id).map(o => Object.assign(o, { b: BOOKINGS.find(b => b.id === o.booking) || { id: o.booking || '—', travel: o.travel } })).sort((a, b) => b.created - a.created); }
route('/p/vendor', () => { const v = me('vendor'); const P = VPRODUCTS.filter(p => p.vendor === v.id); const O = vOrders(v);
  return { html: `<div class="page">${pHead('vendor', v.name, L3(['Dashboard vendor — produk, order dari Travel, saldo, dan verifikasi.', 'Vendor dashboard — products, orders from Travels, balance and verification.', 'لوحة المورد.']))}<div style="display:flex;gap:6px;flex-wrap:wrap;margin:-6px 0 14px">${portalBadge('vendor')}<span class="chip mono">${v.id}</span>${st(v.status)}${st(v.verif)}${v.cats.map(c => `<span class="chip">${c}</span>`).join('')}</div>
  ${v.verif !== 'verified' ? `<div class="banner warn" style="border:1px solid var(--warn-line);border-radius:10px;margin-bottom:14px">${ic('alert')}<span style="flex:1">${L3(['Akun belum terverifikasi — produk tidak bisa diajukan ke Marketplace dan withdrawal belum tersedia.', 'Account not verified — products cannot be submitted to the Marketplace and withdrawals are unavailable.', 'غير موثق.'])}</span><a class="btn sm" href="#/p/vendor/documents">${L3(['Lengkapi verifikasi', 'Complete verification', 'أكمل التحقق'])}</a></div>` : ''}
  ${kpiRow([{ k: L3(['Order perlu diproses', 'Orders to process', 'طلبات']), v: fN(O.filter(o => o.state === 'pending').length), icon: 'list' }, { k: 'GMV 30d', v: money(v.gmv30), icon: 'trend' }, { k: L3(['Saldo tersedia', 'Available balance', 'الرصيد']), v: money(v.balance), icon: 'wallet' }, { k: L3(['Produk published', 'Published products', 'منشورة']), v: P.filter(p => p.state === 'published').length + ' / ' + P.length, icon: 'package' }])}
  <div class="grid g2" style="margin-top:14px">${pnl('Order', tbl(['PO', 'Travel', 'Nilai', t('status')], O.slice(0, 6).map(o => rowLink('/p/vendor/orders', `<td class="mono">${o.id}</td><td>${esc((travelById(o.travel) || {}).name || o.travel)}</td><td class="r tnum">${money(o.value)}</td><td>${st(o.state)}</td>`))), { raw: true, icon: 'list', right: `<a class="btn sm ghost" href="#/p/vendor/orders">${t('see_all')}${icd('chevR', 'sm')}</a>` })}${pnl(L3(['Produk', 'Products', 'المنتجات']), tbl([L3(['Produk', 'Product', 'المنتج']), 'Harga', t('status')], P.slice(0, 6).map(p => rowLink('/p/vendor/products', `<td>${esc(p.name)}</td><td class="r tnum">${money(p.price)}</td><td>${st(p.state)}</td>`))), { raw: true, icon: 'package' })}</div></div>` }; });
route('/p/vendor/products', () => { const v = me('vendor'); const P = VPRODUCTS.filter(p => p.vendor === v.id); const ok = v.verif === 'verified';
  return { html: `<div class="page">${pHead('vendor', L3(['Produk & Layanan', 'Products & Services', 'المنتجات']), L3(['Buat produk sebagai draft lalu ajukan review. Publikasi dilakukan moderator Segaloka.', 'Create products as drafts, then submit for review. Segaloka moderators publish them.', 'المنتجات.']), `<button class="btn primary" data-act="vp-new">${ic('plus')}${L3(['Tambah produk', 'Add product', 'إضافة'])}</button>`)}<section class="panel">${tbl([L3(['Produk', 'Product', 'المنتج']), L3(['Kategori', 'Category', 'الفئة']), 'Harga', 'Allotment', t('status'), ''], P.map(p => `<tr><td><b>${esc(p.name)}</b><div class="muted mono" style="font-size:11.5px">${p.id}</div></td><td>${p.cat}</td><td class="r tnum">${money(p.price)} <span class="muted">${p.unit}</span></td><td class="r"><input type="number" value="${p.allot}" min="0" style="width:80px;border:1px solid var(--line-strong);border-radius:6px;padding:4px 6px;background:var(--surface)" data-act-change="vp-allot" data-id="${p.id}" aria-label="Allotment"></td><td>${st(p.state)}</td><td class="r">${p.state === 'draft' ? `<button class="btn sm primary" data-act="vp-set" data-id="${p.id}" data-v="review" ${ok ? '' : `aria-disabled="true" data-tip="${esc(L3(['Vendor belum terverifikasi', 'Vendor not verified', 'غير موثق']))}"`}>${t('submit_review')}</button>` : p.state === 'published' ? `<button class="btn sm badb" data-act="vp-set" data-id="${p.id}" data-v="unpublished">Unpublish</button>` : p.state === 'unpublished' ? `<button class="btn sm" data-act="vp-set" data-id="${p.id}" data-v="review">${L3(['Ajukan ulang', 'Resubmit', 'إعادة'])}</button>` : ''}</td></tr>`))}</section></div>` }; });
Object.assign(A, {
  'vp-new': () => { const v = me('vendor'); modal({ title: L3(['Tambah produk', 'Add product', 'إضافة منتج']), body: fields([{ k: 'name', label: L3(['Nama', 'Name', 'الاسم']), req: true }, { k: 'cat', label: L3(['Kategori', 'Category', 'الفئة']), type: 'select', options: v.cats }, { k: 'price', label: 'Harga (Rp)', type: 'number', req: true, step: 10000 }, { k: 'unit', label: 'Unit', def: '/pax' }, { k: 'allot', label: 'Allotment', type: 'number', def: 50 }], 'vp-'), foot: `<button class="btn" data-act="close">${t('cancel')}</button><button class="btn primary" data-act="vp-save">${t('save')}</button>` }); },
  'vp-save': () => { const v = formVals([{ k: 'name', req: true }, { k: 'cat' }, { k: 'price', type: 'number', req: true }, { k: 'unit' }, { k: 'allot', type: 'number' }], 'vp-'); if (!v) return; const p = { id: uid('VP'), ...v, vendor: me('vendor').id, state: 'draft' }; VPRODUCTS.unshift(p); pAudit('vendor', 'vendor_product.create', 'VendorProduct/' + p.id); closeOverlays(); toast('ok', L3(['Produk dibuat', 'Product created', 'أُنشئ']), p.name); rerender(); },
  'vp-set': el => { const p = VPRODUCTS.find(x => x.id === el.dataset.id); const prev = p.state; p.state = el.dataset.v; pAudit('vendor', 'vendor_product.' + p.state, 'VendorProduct/' + p.id, { before: prev, after: p.state }); if (p.state === 'review') pNotif('marketplace', 'info', L3(['Produk vendor menunggu moderasi', 'Vendor product awaiting moderation', 'بانتظار المراجعة']), p.name, '/marketplace/moderation'); toast('ok', p.name + ' → ' + L3(STATUS[p.state].slice(2)), ''); rerender(); },
  'vp-allot': el => { const p = VPRODUCTS.find(x => x.id === el.dataset.id); const prev = p.allot; p.allot = +el.value; pAudit('vendor', 'vendor_product.allotment', 'VendorProduct/' + p.id, { before: String(prev), after: el.value }); toast('ok', 'Allotment · ' + p.name, prev + ' → ' + el.value); }
});
route('/p/vendor/orders', () => { const v = me('vendor'); const O = vOrders(v); return { html: `<div class="page">${pHead('vendor', 'Order', L3(['Order layanan dari Travel. Order selesai menambah saldo (dipotong fee marketplace 5%).', 'Service orders from Travels. Completed orders add to your balance (minus the 5% marketplace fee).', 'الطلبات.']))}<section class="panel">${tbl(['PO', 'Travel', L3(['Produk', 'Product', 'المنتج']), 'Nilai', t('status'), ''], O.map(o => `<tr><td class="mono">${o.id}</td><td>${esc((travelById(o.travel) || {}).name || o.travel)}</td><td>${esc(o.productName || o.product)} × ${fN(o.qty)}</td><td class="r tnum">${money(o.value)}</td><td>${st(o.state)}</td><td class="r">${o.state === 'pending' ? `<div class="actions" style="justify-content:flex-end"><button class="btn sm badb" data-act="vo-set" data-id="${o.id}" data-v="cancelled">${t('reject')}</button><button class="btn sm primary" data-act="vo-set" data-id="${o.id}" data-v="confirmed">${L3(['Terima', 'Accept', 'قبول'])}</button></div>` : o.state === 'confirmed' ? `<button class="btn sm" data-act="vo-set" data-id="${o.id}" data-v="completed">${L3(['Tandai selesai', 'Mark completed', 'مكتمل'])}</button>` : ''}</td></tr>`), L3(['Belum ada order dari Travel', 'No orders from Travels yet', 'لا طلبات']))}</section></div>` }; });
A['vo-set'] = el => { const o = VORDERS.find(x => x.id === el.dataset.id); if (!o) return; const prev = o.state; o.state = el.dataset.v; o.updated = nowTs(); if (o.state === 'cancelled' && prev === 'pending') { const vp = VPRODUCTS.find(x => x.id === o.product); if (vp) vp.allot = (vp.allot || 0) + o.qty; } pAudit('vendor', 'vendor_order.' + o.state, 'VendorOrder/' + o.id, { before: prev, after: o.state }); pNotif('travel', o.state === 'cancelled' ? 'warn' : 'ok', 'Order ' + o.id + ' → ' + L3(STATUS[o.state].slice(2)), (vendorById(o.vendor) || {}).name || o.vendor, '/p/travel/vendors'); recompute(); toast('ok', o.id + ' → ' + L3(STATUS[o.state].slice(2)), o.state === 'completed' ? '+' + money(o.value * .95) + ' ' + L3(['ke saldo vendor', 'to vendor balance', 'للرصيد']) : ''); rerender(); };
route('/p/vendor/finance', () => { const v = me('vendor'); const wd = WITHDRAWALS.filter(w => w.ref === v.id); return { html: `<div class="page">${pHead('vendor', L3(['Keuangan', 'Finance', 'المالية']), L3(['Pembayaran vendor melalui Segaloka; withdrawal mengikuti order yang selesai dan butuh approval Finance.', 'Vendor payments go through Segaloka; withdrawals follow completed orders and need Finance approval.', 'المالية.']), `<button class="btn primary" data-act="wd-req" data-ws="vendor" ${v.verif === 'verified' && v.status !== 'inactive' ? '' : `aria-disabled="true" data-tip="${esc(L3(['Vendor harus terverifikasi & aktif', 'Vendor must be verified & active', 'يجب التوثيق']))}"`}>${ic('arrowur')}${L3(['Tarik saldo', 'Withdraw', 'سحب'])}</button>`)}${kpiRow([{ k: L3(['Saldo tersedia', 'Available', 'متاح']), v: money(v.balance) }, { k: L3(['Dalam proses', 'In progress', 'قيد المعالجة']), v: money(wd.filter(w => ['pending', 'approved', 'hold'].includes(w.state)).reduce((s, w) => s + w.amount, 0)) }, { k: L3(['Sudah dicairkan', 'Disbursed', 'مصروف']), v: money(wd.filter(w => w.state === 'disbursed').reduce((s, w) => s + w.amount, 0)) }, { k: 'Fee', v: '5%' }])}<section class="panel" style="margin-top:14px">${tbl(['ID', 'Amount', 'Basis', t('status'), L3(['Waktu', 'Time', 'الوقت'])], wd.map(w => `<tr><td class="mono">${w.id}</td><td class="r tnum">${money(w.amount, true)}</td><td>${esc(w.basis)}</td><td>${st(w.state)}</td><td>${rel(w.ts)}</td></tr>`), L3(['Belum ada withdrawal', 'No withdrawals yet', 'لا سحوبات']))}</section></div>` }; });
route('/p/vendor/documents', () => { const v = me('vendor'); v.docs = v.docs || {}; const D0 = ['Commercial registration / NIB', 'NPWP / Tax ID', L3(['Kontrak kerja sama', 'Partnership agreement', 'العقد']), L3(['Rekening bank', 'Bank account', 'الحساب البنكي'])]; const ds = n => v.docs[n] || (v.verif === 'verified' ? 'verified' : 'pending');
  return { html: `<div class="page">${pHead('vendor', L3(['Dokumen & Verifikasi', 'Documents & Verification', 'المستندات']), L3(['Unggah dokumen, lalu ajukan verifikasi. Tim Compliance Segaloka memutuskan di Approval Center.', 'Upload documents, then submit for verification. Segaloka Compliance decides in the Approval Center.', 'المستندات.']), v.verif === 'verified' ? st('verified') : `<button class="btn primary" data-act="vd-submit" ${D0.every(n => ['submitted', 'verified'].includes(ds(n))) && !['submitted', 'under_review'].includes(v.verif) ? '' : `aria-disabled="true" data-tip="${esc(['submitted', 'under_review'].includes(v.verif) ? L3(['Sudah diajukan', 'Already submitted', 'مُرسل']) : L3(['Unggah semua dokumen dulu', 'Upload all documents first', 'ارفع كل المستندات']))}"`}>${t('submit_review')}</button>`)}<section class="panel" style="padding:12px 14px;margin-bottom:14px">${lifeBar(['draft', 'submitted', 'under_review', 'verified'], v.verif === 'rejected' ? 'under_review' : v.verif, v.verif === 'rejected' ? 'rejected' : null)}</section>${pnl(L3(['Dokumen', 'Documents', 'المستندات']), D0.map(n => `<div class="docrow"><span class="fi">PDF</span><span class="body"><b>${esc(n)}</b><span>${L3(STATUS[ds(n)].slice(2))}</span></span>${st(ds(n))}${ds(n) === 'verified' ? '' : `<button class="btn sm" data-act="vd-up" data-n="${esc(n)}">${ic('upload', 'sm')}${L3(['Unggah', 'Upload', 'رفع'])}</button>`}</div>`).join(''), { icon: 'folder' })}</div>` }; });
Object.assign(A, {
  'vd-up': el => { const v = me('vendor'); const inp = document.createElement('input'); inp.type = 'file'; inp.onchange = () => { v.docs = v.docs || {}; v.docs[el.dataset.n] = 'submitted'; pAudit('vendor', 'vendor.document.upload', 'Vendor/' + v.id + '/' + el.dataset.n, { after: inp.files[0] ? inp.files[0].name : '' }); toast('ok', L3(['Dokumen diunggah', 'Document uploaded', 'رُفع']), el.dataset.n); rerender(); }; inp.click(); },
  'vd-submit': () => { const v = me('vendor'); v.verif = 'submitted'; if (v.status === 'inactive') v.status = 'review'; const a = pApproval({ type: 'vendor_verif', domain: 'Vendor', title: 'Verifikasi vendor — ' + v.name, requester: v.name, reqRef: v.id, reqRoute: '/vendor/' + v.id + '/documents', docs: Object.keys(v.docs || {}).map(n => ['PDF', n, '—']), ctx: [['Kategori', v.cats.join(', ')], ['Negara', v.country]], source: 'Portal Vendor' }); pAudit('vendor', 'vendor.verification.submit', 'Vendor/' + v.id); pNotif('approval', 'info', L3(['Verifikasi vendor diajukan', 'Vendor verification submitted', 'طلب توثيق']), v.name, '/approval/' + a.id); toast('ok', L3(['Verifikasi diajukan', 'Verification submitted', 'أُرسل']), 'Approval Center'); rerender(); }
});
